/* Halcyon Threshold — Site Styles */

:root {
    --text: #1a1a2e;
    --bg: #fafafa;
    --accent: #4a5568;
    --link: #2c5282;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
    line-height: 1.7;
    color: var(--text);
    background: var(--bg);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

main {
    max-width: 640px;
    margin: 0 auto;
    padding: 4rem 2rem;
    flex: 1;
}

h1 {
    font-size: 2.5rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    letter-spacing: -0.02em;
}

.tagline {
    font-size: 1.1rem;
    color: var(--accent);
    margin-bottom: 3rem;
    font-style: italic;
}

section {
    margin-bottom: 2.5rem;
}

h2 {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: 0.75rem;
    color: var(--accent);
}

p {
    margin-bottom: 1rem;
}

a {
    color: var(--link);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: border-color 0.2s;
}

a:hover {
    border-bottom-color: var(--link);
}

footer {
    text-align: center;
    padding: 2rem;
    color: var(--accent);
    font-size: 0.875rem;
}

@media (max-width: 480px) {
    main {
        padding: 2rem 1.5rem;
    }

    h1 {
        font-size: 2rem;
    }
}

